	private static final class ServiceOutputVariableCollector extends AbstractQueryModelVisitor<RuntimeException> {
		private final Set<String> bindingNames = new LinkedHashSet<>();

		@Override
		public void meet(Var node) {
			addVariable(node);
		}

		@Override
		public void meet(StatementPattern node) {
			addVariable(node.getSubjectVar());
			addVariable(node.getPredicateVar());
			addVariable(node.getObjectVar());
			addVariable(node.getContextVar());
		}

		@Override
		public void meet(TripleRef node) {
			for (Var variable : node.getVarList()) {
				addVariable(variable);
			}
		}

		@Override
		public void meet(ArbitraryLengthPath node) {
			addVariable(node.getSubjectVar());
			addVariable(node.getObjectVar());
			addVariable(node.getContextVar());
		}

		@Override
		public void meet(ZeroLengthPath node) {
			addVariable(node.getSubjectVar());
			addVariable(node.getObjectVar());
			addVariable(node.getContextVar());
		}

		@Override
		public void meet(BindingSetAssignment node) {
			bindingNames.addAll(node.getBindingNames());
		}

		@Override
		public void meet(Filter node) {
			node.getArg().visit(this);
		}

		@Override
		public void meet(LeftJoin node) {
			node.getLeftArg().visit(this);
			node.getRightArg().visit(this);
		}

		@Override
		public void meet(Difference node) {
			node.getLeftArg().visit(this);
		}

		@Override
		public void meet(Intersection node) {
			Set<String> leftNames = collect(node.getLeftArg());
			leftNames.retainAll(collect(node.getRightArg()));
			bindingNames.addAll(leftNames);
		}

		@Override
		public void meet(Projection node) {
			bindingNames.addAll(node.getBindingNames());
			if (!node.isSubquery()) {
				node.getArg().visit(this);
			}
		}

		@Override
		public void meet(MultiProjection node) {
			bindingNames.addAll(node.getBindingNames());
		}

		@Override
		public void meet(Group node) {
			bindingNames.addAll(node.getBindingNames());
		}

		@Override
		public void meet(Order node) {
			node.getArg().visit(this);
		}

		@Override
		public void meet(Extension node) {
			for (ExtensionElem element : node.getElements()) {
				bindingNames.add(element.getName());
			}
			node.getArg().visit(this);
		}

		@Override
		public void meet(Service node) {
			bindingNames.addAll(node.getServiceOutputBindingNames());
		}

		@Override
		public void meetOther(QueryModelNode node) {
			if (node instanceof TupleExpr tupleExpr) {
				bindingNames.addAll(tupleExpr.getBindingNames());
			} else {
				super.meetOther(node);
			}
		}

		private void addVariable(Var variable) {
			if (variable != null && !variable.isConstant() && !variable.isAnonymous()) {
				bindingNames.add(variable.getName());
			}
		}

		private Set<String> collect(TupleExpr expression) {
			ServiceOutputVariableCollector collector = new ServiceOutputVariableCollector();
			expression.visit(collector);
			return collector.bindingNames;
		}
	}

	private static final class ScopeVisitor extends AbstractQueryModelVisitor<RuntimeException> {
		private boolean service;
		private boolean localSubquery;

		@Override
		public void meet(Service node) {
			// A nested SERVICE owns its own remote scope and is atomic to the enclosing tuple scope.
			service = true;
		}

		@Override
		public void meet(Projection node) {
			if (node.isSubquery()) {
				localSubquery = true;
			} else {
				node.getArg().visit(this);
			}
		}

		@Override
		public void meet(Filter node) {
			// EXISTS and NOT EXISTS conditions are value-expression scope, not tuple output scope.
			node.getArg().visit(this);
		}

		@Override
		public void meet(LeftJoin node) {
			node.getLeftArg().visit(this);
			node.getRightArg().visit(this);
		}

		@Override
		public void meet(Extension node) {
			node.getArg().visit(this);
		}

		@Override
		public void meet(Order node) {
			node.getArg().visit(this);
		}

		@Override
		public void meet(Group node) {
			node.getArg().visit(this);
		}

		@Override
		public void meet(MultiProjection node) {
			node.getArg().visit(this);
		}

		@Override
		public void meet(Exists node) {
			// EXISTS is a value expression and cannot establish a tuple scope for its enclosing operand.
		}
	}

	private void initPreparedQueryString() {

		serviceExpressionString = serviceExpressionString.trim();
		String prefixString = computePrefixString(prefixDeclarations);

		// build the raw SELECT query string
		StringBuilder sb = new StringBuilder();
		sb.append(prefixString);
		if (subselectPattern.matcher(serviceExpressionString).matches()) {
			sb.append(serviceExpressionString);
		} else {
			sb.append("SELECT %PROJECTION_VARS% WHERE { ");
			sb.append(serviceExpressionString);
			sb.append("\n}");
		}
		preparedSelectQueryString = sb.toString();

		// build the raw ASK query string
		sb = new StringBuilder();
		sb.append(prefixString);
		sb.append("ASK {");
		sb.append(serviceExpressionString);
		sb.append(" }");
		preparedAskQueryString = sb.toString();
	}

	/**
	 * Compute the prefix string only once to avoid computation overhead during evaluation.
	 *
	 * @param prefixDeclarations
	 * @return a Prefix String or an empty string if there are no prefixes
	 */
	private String computePrefixString(Map<String, String> prefixDeclarations) {
		if (prefixDeclarations == null) {
			return "";
		}

		StringBuilder sb = new StringBuilder();
		for (String prefix : prefixDeclarations.keySet()) {
			String uri = prefixDeclarations.get(prefix);
			sb.append("PREFIX ").append(prefix).append(":").append(" <").append(uri).append("> ");
		}
		return sb.toString();
	}

	/**
	 * Parses a service expression to just have the inner expression, e.g. from something like "SERVICE &lt;url&gt; {
	 * ... }" becomes " ... ", also applies {@link String#trim()} to remove leading/tailing space
	 *
	 * @param serviceExpression
	 * @return the inner expression of the given service expression
	 */
	private String parseServiceExpression(String serviceExpression) {

		if (serviceExpression.toLowerCase().startsWith("service")) {
			return serviceExpression.substring(serviceExpression.indexOf('{') + 1, serviceExpression.lastIndexOf('}'))
					.trim();
		}
		return serviceExpression;
	}

